// === Tab: mySketch ===
//let Of Influence
//Instagram - @fuzzylogic.io
//Tumblr - @fuzzylogic-io
//Twitter - @fuzzylogic_io
//Reddit - @fuzzylogic-io
//let of https://openprocessing.org/sketch/729004

let mainradius = 300; //大きさ
let Yangle = 0;　//回転
let speed = 0.01; //回転スピード
let offset = 10;　//水平、垂直で値を設定
let ring = 2.75; //遊動リング

function setup() {
	createCanvas(500, 500, WEBGL); //サイズを指定、立体に
	frameRate(40); //フレームレートを指定
}

function draw() {
	if (keyPressed) {　//キーボードを押したら
		if (key == CODED) {　//コード化されたキーが押された
			if (keyCode == UP) { //↑を押すと
				ring += 1; //リングがプラスされる
			}
			if (keyCode == DOWN) { //↓を押すと
				if (ring > 1) { //リングが1以上の時
					ring -= 1; //リングがマイナスされる
				}
			}
		}
	}
	background(0); //背景が黒
	translate(250, 250); //ディスプレイウィンドウの中心座標を変える
	rotateY(Yangle);
	rotateX(-90);
	rotateZ(-10);
	for (y = -mainradius / 2; y < mainradius / 2; y += round(ring)) {
		strokeWeight(ring * sin(y + offset)); //線の太さ
		let t = 0;
		while (t < TWO_PI) { //円の円周と直径の比の2倍の値がtより大きい時（繰り返し）
			let radius = sqrt(pow((mainradius - 40) / 2, 2) - pow(y, 2)); //平方根の設定？
			let x = radius * cos(t); //
			let z = radius * sin(t);
			stroke(map(sin(y + offset), -1, 1, 0, 255)); //線の色と場所？
			point(x, y, z);
			t += 0.1;
		}
	}
	Yangle += speed; 
	offset += 0.1; //回転中心の移動量の設定
}

